'use strict';

// Phase 1 verification: byte-exact comparison of the JS engine
// (Rank2Orchestration.js) against real compiled FFTW3 output (fixtures
// generated by ground_truth_harness.c). This is the actual "done" criterion
// for Phase 1 -- see the project plan.

const { rdft2R2c, rdft2C2r } = require('../Rank2Orchestration.js');
const { readFixture, compareBuffers, reportComparison } = require('./compare.js');
const path = require('path');

const FIXTURES = path.join(__dirname, 'fixtures');
const PAIRS = [
  [37, 37], [43, 43], [47, 47], [37, 43], [43, 47], [57, 53],
  // 20 and 12 exercise PlanTable.js's newly-widened column coverage
  // (isDirectOnlyComplex): standalone-direct column sizes, proven immune
  // to the embedded/vector-loop NO_VRECURSE divergence documented in
  // PlanTable.js's header (unlike N=64, which looked safe standalone --
  // see this project's git history / session notes -- but silently
  // diverges to a different codelet once embedded in a 2D r2c plan; caught
  // by this exact random-input test before it was ever promoted). Row
  // sizes (37, 43) stay in the already-verified odd-prime set to isolate
  // the column-axis widening from the row-axis one.
  [20, 37], [12, 43],
  // 20x49 exercises PlanTable.js's row-axis widening: N1=49=7x7 uses
  // hf_7/hb_7 (radix-7 twiddle codelets, newly ported) as BOTH the outer
  // combine and the Stage-2 DC-combine radix -- the one composite-row
  // shape proven safe so far (radix 3 in the same role was found to
  // silently diverge by a few ULPs -- see RealEngine1D.js's
  // isFullyPortedR2HC header -- and is excluded).
  [20, 49],
];
const INPUTS = ['delta', 'random'];

function makeDeltaReal(N0, N1) {
  const a = new Float64Array(N0 * N1);
  a[0] = 1.0;
  return a;
}

function makeRandomReal(N0, N1) {
  // Must match ground_truth_harness.c's fill_random EXACTLY (srand(42) +
  // rand()/RAND_MAX*2-1) to compare against the same fixture -- but C's
  // rand() isn't reproducible from JS. Instead, read the fixture's OWN
  // input back out is not possible (harness only dumps output, not the
  // random input it generated). So for "random" cases we instead feed the
  // JS engine the FORWARD-direction random fixture's output back into the
  // INVERSE transform (for inv tests), and for fwd tests we regenerate the
  // input by asking the harness to dump it -- see loadOrRegenInput below.
  throw new Error('use loadRandomRealInput instead');
}

const { execFileSync } = require('child_process');
const fs = require('fs');

// For "random" fwd tests we need the SAME random input C used. Simplest
// robust approach: ask the harness itself to write the random real array
// to a file via a small helper mode, OR reuse fixtures/fwd_*_random.bin's
// own generation determinism by re-invoking the harness's fill_random via
// a tiny throwaway C call is overkill -- instead, generate the input here
// in JS with the SAME algorithm (srand(42)-equivalent) is fragile across
// platforms' rand() implementations. Cleanest: dump the input from C once
// per size via a one-off "echo" trick using the harness's existing 'file'
// mode is circular. So: for random fwd cases, we derive input
// deterministically in JS and ALSO regenerate the C fixture from that same
// input via the harness's file mode, so both sides provably see identical
// input. This runs the harness as a subprocess directly from this test.
function jsRandomReal(N0, N1, seed) {
  // xorshift32, seeded, deterministic in JS -- independent of C's rand(),
  // but we feed this SAME array to the C harness via file-mode below, so
  // both sides transform provably identical input regardless of what PRNG
  // produced it.
  let s = seed >>> 0;
  const next = () => {
    s ^= s << 13; s >>>= 0;
    s ^= s >>> 17;
    s ^= s << 5; s >>>= 0;
    return s;
  };
  const a = new Float64Array(N0 * N1);
  for (let i = 0; i < a.length; i++) {
    a[i] = (next() / 4294967295) * 2 - 1;
  }
  return a;
}

function writeDoubles(filePath, arr) {
  const buf = Buffer.alloc(arr.length * 8);
  for (let i = 0; i < arr.length; i++) buf.writeDoubleLE(arr[i], i * 8);
  fs.writeFileSync(filePath, buf);
}

function harnessFwd(N0, N1, inputPath, outputPath) {
  execFileSync(path.join(__dirname, 'ground_truth_harness'),
    ['fwd', String(N0), String(N1), 'file', inputPath, outputPath]);
}

function harnessInv(N0, N1, inputPath, outputPath) {
  execFileSync(path.join(__dirname, 'ground_truth_harness'),
    ['inv', String(N0), String(N1), 'file', inputPath, outputPath]);
}

let allPass = true;
const tmp = require('os').tmpdir();

for (const [N0, N1] of PAIRS) {
  // --- delta forward ---
  {
    const real = makeDeltaReal(N0, N1);
    const jsOut = rdft2R2c(N0, N1, real);
    const expected = readFixture(path.join(FIXTURES, `fwd_${N0}x${N1}_delta.bin`));
    const result = compareBuffers(expected, jsOut);
    allPass = reportComparison(`fwd ${N0}x${N1} delta`, result) && allPass;
  }

  // --- random forward (regenerate C fixture from JS's own random input,
  //     so both sides transform identical data) ---
  {
    const real = jsRandomReal(N0, N1, 12345 + N0 * 1000 + N1);
    const inPath = path.join(tmp, `phase1_in_${N0}x${N1}.bin`);
    const outPath = path.join(tmp, `phase1_out_${N0}x${N1}.bin`);
    writeDoubles(inPath, real);
    harnessFwd(N0, N1, inPath, outPath);
    const jsOut = rdft2R2c(N0, N1, real);
    const expected = readFixture(outPath);
    const result = compareBuffers(expected, jsOut);
    allPass = reportComparison(`fwd ${N0}x${N1} random`, result) && allPass;
  }

  // --- delta inverse (unit DC bin) ---
  {
    const NC = Math.floor(N1 / 2) + 1;
    const complexIn = new Float64Array(N0 * NC * 2);
    complexIn[0] = 1.0;
    const jsOut = rdft2C2r(N0, N1, complexIn);
    const expected = readFixture(path.join(FIXTURES, `inv_${N0}x${N1}_delta.bin`));
    const result = compareBuffers(expected, jsOut);
    allPass = reportComparison(`inv ${N0}x${N1} delta`, result) && allPass;
  }

  // --- random inverse ---
  {
    const NC = Math.floor(N1 / 2) + 1;
    // Reuse the forward-random complex output as a well-formed complex
    // input for the inverse test (arbitrary but deterministic and
    // reproducible on both sides via the same file-based round trip).
    const real = jsRandomReal(N0, N1, 54321 + N0 * 1000 + N1);
    const inPath = path.join(tmp, `phase1_invin_real_${N0}x${N1}.bin`);
    const fwdOutPath = path.join(tmp, `phase1_invin_complex_${N0}x${N1}.bin`);
    writeDoubles(inPath, real);
    harnessFwd(N0, N1, inPath, fwdOutPath);
    const complexIn = readFixture(fwdOutPath);

    const invOutPath = path.join(tmp, `phase1_inv_out_${N0}x${N1}.bin`);
    harnessInv(N0, N1, fwdOutPath, invOutPath);

    const jsOut = rdft2C2r(N0, N1, complexIn);
    const expected = readFixture(invOutPath);
    const result = compareBuffers(expected, jsOut);
    allPass = reportComparison(`inv ${N0}x${N1} random`, result) && allPass;
  }
}

console.log(allPass ? '\n=== ALL PASS ===' : '\n=== FAILURES ABOVE ===');
process.exit(allPass ? 0 : 1);
